using System;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.IO;using UnityEngine;using UnityEditor;
public static class DrpgPhase7Validation {
 [MenuItem("Editor/DRPG/Fase 7/Verificar contratos y perfiles")]
 public static string Run(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Ejecutar fuera de Play Mode");var result=new List<string>();Action<bool,string> check=(value,label)=>result.Add((value?"PASS ":"FAIL ")+label);var profile=PlayerProfileSettings.Current;var original=DungeonMapSettings.Current;var provider=Resources.Load<ManualMapProvider>("MapProviders/OriginalManual");var f=BindingFlags.Instance|BindingFlags.NonPublic;
  check(profile!=null&&profile.Validate().Count==0,"GamerBoy profile has all existing references");check(profile.character==Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings"),"Character/equipment asset reused");check(profile.levels==PlayerLevelSettings.Current&&profile.bits==PlayerBitsSettings.Current,"Growth and Bits settings reused");check(profile.inventory==Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings")&&profile.hacks==PlayerHackCatalog.Current,"Inventory and HACK catalog reused");
  var empty=ScriptableObject.CreateInstance<PlayerProfileSettings>();empty.id="";check(empty.Validate().Count==6,"Incomplete profile diagnosed");UnityEngine.Object.DestroyImmediate(empty);
  IMapProvider contract=provider;var definition=contract.CreateDefinition();check(definition.Source==original&&definition.MapId==original.mapId,"Manual provider preserves source and mapId");check(definition.Rows.SequenceEqual(original.rows),"Manual geometry unchanged");check(definition.Entities==original.entities&&definition.Regions==original.regions,"Existing region and entity definitions reused");check(definition.StartCell==original.startCell&&definition.StartHeading==original.startHeading,"Spawn pose unchanged");check(definition.SnapshotKey==original.mapId&&!definition.Origin.hasSeed&&definition.Origin.providerId=="manual","Manual snapshot IDs remain compatible");
  var rows=definition.Rows;rows[0]="bad";check(definition.Rows[0]==original.rows[0]&&original.Valid,"Rows exposed as copies");var origin=definition.Origin;origin.algorithmVersion=99;check(definition.Origin.algorithmVersion==1,"Origin metadata exposed as copy");
  var seeded=new DungeonMapDefinition(original,new DungeonMapOrigin{providerId="future-test",algorithmVersion=1,hasSeed=true,seed=1});var otherSeed=new DungeonMapDefinition(original,new DungeonMapOrigin{providerId="future-test",algorithmVersion=1,hasSeed=true,seed=2});var otherVersion=new DungeonMapDefinition(original,new DungeonMapOrigin{providerId="future-test",algorithmVersion=2,hasSeed=true,seed=1});check(seeded.SnapshotKey!=otherSeed.SnapshotKey&&seeded.SnapshotKey!=otherVersion.SnapshotKey,"Future seed/version namespaces are distinct (no generation)");
  var invalid=ScriptableObject.CreateInstance<DungeonMapSettings>();invalid.rows=new[]{"###","#.#","###"};bool rejected=false;try{ManualMapProvider.Capture(invalid);}catch(ArgumentException){rejected=true;}check(rejected,"Missing stable map ID rejected");invalid.mapId="fixture.invalid";invalid.rows=new[]{"##","#.#"};rejected=false;try{ManualMapProvider.Capture(invalid);}catch(ArgumentException){rejected=true;}check(rejected,"Malformed manual map rejected");UnityEngine.Object.DestroyImmediate(invalid);
  rejected=false;try{new DungeonMapDefinition(original,new DungeonMapOrigin{algorithmVersion=0});}catch(ArgumentException){rejected=true;}check(rejected,"Invalid origin version rejected");var fallback=ScriptableObject.CreateInstance<ManualMapProvider>();check(fallback.CreateDefinition(original).MapId==original.mapId,"Explicit fallback map supported");UnityEngine.Object.DestroyImmediate(fallback);
  var host=new GameObject("Phase7 contract fixture");var d=host.AddComponent<DungeonPrototype>();d.enabled=false;d.playerProfile=profile;typeof(DungeonPrototype).GetMethod("ApplyPlayerProfileDefaults",f).Invoke(d,null);check(d.characterSettings==profile.character&&d.playerLevelSettings==profile.levels&&d.playerBitsSettings==profile.bits&&d.inventorySettings==profile.inventory&&d.playerHackCatalog==profile.hacks,"Controller consumes all profile references");
  var explicitCharacter=UnityEngine.Object.Instantiate(profile.character);d.characterSettings=explicitCharacter;typeof(DungeonPrototype).GetMethod("ApplyPlayerProfileDefaults",f).Invoke(d,null);check(d.characterSettings==explicitCharacter,"Explicit controller override wins over profile default");d.mapSettings=original;d.mapProvider=provider;check(d.CurrentMapDefinition.Rows.SequenceEqual(original.rows),"Controller consumes manual provider contract");d.mapSettings=Resources.Load<DungeonMapSettings>("DrpgPhase6Tests/FloorA");check(d.CurrentMapDefinition.MapId==d.mapSettings.mapId,"Provider for another floor cannot replace travel destination");UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(explicitCharacter);
  check(!Resources.LoadAll<PlayerProfileSettings>("Combat").Any(p=>p.id!="gamerboy"),"No new playable character profile");check(typeof(IMapProvider).Assembly.GetType("ProceduralMapProvider")==null&&typeof(IMapProvider).Assembly.GetType("HybridMapProvider")==null,"No procedural or hybrid generator implemented");
  string summary=result.Count(x=>x.StartsWith("PASS"))+" passed / "+result.Count(x=>x.StartsWith("FAIL"))+" failed";File.WriteAllLines("Tests/DrpgPhase7Results.txt",new[]{summary}.Concat(result));Debug.Log("Phase7: "+summary);return summary;
 }
}
